"""/data/nemesis/bin/mount, generated by install_mount_wrap in native/util.c.

Requirement: AGENTS.md section 3 and 02-Debugging-Execution-Interface.md section 4.
A remount of /system goes to `nemesis remount`, and everything else reaches real mount.
"""
from __future__ import annotations

import re

import pytest

from helpers import NATIVE, known_bug
from sandbox import SH, Unit, sh_path, stub, write_lf

pytestmark = pytest.mark.skipif(not SH, reason="needs a POSIX sh")


def wrapper_source() -> str:
    source = (NATIVE / "util.c").read_text(encoding="utf-8")
    block = re.search(r"wrap\[\]\s*=\s*(.*?);\n", source, re.S).group(1)
    parts = re.findall(r'"((?:[^"\\]|\\.)*)"', block)
    return "".join(parts).replace('\\"', '"').replace("\\n", "\n")


@pytest.fixture
def run(tmp_path):
    unit = Unit(tmp_path)
    stub(unit.path("/system/xbin/nemesis"), 'echo "NEMESIS $*"\n')
    stub(unit.path("/system/bin/mount"), 'echo "REAL $*"\n')
    script = unit.path("wrap.sh")
    write_lf(script, wrapper_source().replace("/system/xbin/nemesis", f"{unit.root}/system/xbin/nemesis").replace("/system/bin/mount", f"{unit.root}/system/bin/mount"))

    def go(*args):
        return unit.run(sh_path(script), *args, cwd=tmp_path).stdout.strip()

    return go


@pytest.mark.parametrize(
    "args,expected",
    [
        ("-o remount,rw /system", "NEMESIS remount rw"),
        ("-o remount,ro /system", "NEMESIS remount ro"),
        ("-o remount,rw /", "NEMESIS remount rw"),
        ("-o remount,ro /", "NEMESIS remount ro"),
        ("-o remount /system", "NEMESIS remount rw"),
        ("-t ext4 -o remount,ro /dev/block/x /system", "NEMESIS remount ro"),
    ],
)
def test_system_remount_goes_to_the_cli(run, args, expected):
    assert run(*args.split()) == expected


@pytest.mark.parametrize(
    "args",
    ["-o remount,rw /data", "-o remount,ro /data", "-t ext4 /dev/x /mnt", "/dev/x /mnt/system-like", ""],
)
def test_everything_else_reaches_real_mount(run, args):
    assert run(*args.split()) == f"REAL {args}".strip()


@pytest.mark.parametrize(
    "args,expected",
    [
        ("-o rw,remount /system", "NEMESIS remount rw"),
        ("-o ro,remount /system", "NEMESIS remount ro"),
        ("-o rw,remount /", "NEMESIS remount rw"),
        ("-oro,remount /system", "NEMESIS remount ro"),
        ("-oremount,ro /system", "NEMESIS remount ro"),
    ],
)
def test_option_order_does_not_matter(run, args, expected):
    assert run(*args.split()) == expected
